import{_ as p,a0 as n,w as o,s as d,I as e,x as s,a1 as l,A as a,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在終端顯示圖像縮略圖 | LCTT x X-CMD","titleTemplate":false,"description":"如何在終端顯示圖像縮略圖 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在終端顯示圖像縮略圖 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在終端顯示圖像縮略圖 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190102 How To Display Thumbnail Images In Terminal","title":"如何在終端顯示圖像縮略圖","tag":"201902","desc":""},"relativePath":"201902/20190102 How To Display Thumbnail Images In Terminal.md","filePath":"[post].md"}'),h={name:"201902/20190102 How To Display Thumbnail Images In Terminal.md"};function g(c,i,k,u,b,m){const t=n("Link");return o(),d("div",null,[i[26]||(i[26]=e("h1",{id:"如何在終端顯示圖像縮略圖",tabindex:"-1"},[s("如何在終端顯示圖像縮略圖 "),e("a",{class:"header-anchor",href:"#如何在終端顯示圖像縮略圖","aria-label":"Permalink to “如何在終端顯示圖像縮略圖”"},"​")],-1)),i[27]||(i[27]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2019/01/lsix-720x340.png",alt:""})],-1)),e("p",null,[i[1]||(i[1]=s("不久前，我們討論了 ",-1)),l(t,{href:"https://www.ostechnix.com/how-to-display-images-in-the-terminal/"},{default:a(()=>[...i[0]||(i[0]=[s("Fim",-1)])]),_:1}),i[2]||(i[2]=s("，這是一個輕量級的命令列圖像查看器應用程序，用於從命令列顯示各種類型的圖像，如 bmp、gif、jpeg 和 png 等。今天，我偶然發現了一個名為 ",-1)),i[3]||(i[3]=e("code",null,"lsix",-1)),i[4]||(i[4]=s(" 的類似工具。它類似於類 Unix 系統中的 ",-1)),i[5]||(i[5]=e("code",null,"ls",-1)),i[6]||(i[6]=s(" 命令，但僅適用於圖像。",-1)),i[7]||(i[7]=e("code",null,"lsix",-1)),i[8]||(i[8]=s(" 是一個簡單的命令列實用程序，旨在使用 Sixel 圖形格式在終端中顯示縮略圖。對於那些想知道的人來説，Sixel 是",-1)),i[9]||(i[9]=e("ruby",null,[s("六像素"),e("rt",null,"six pixels")],-1)),i[10]||(i[10]=s("的縮寫，是一種位圖圖形格式。它使用 ImageMagick，因此幾乎所有 imagemagick 支持的文件格式都可以正常工作。",-1))]),i[28]||(i[28]=r('<h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h3><p>關於 <code>lsix</code> 的功能，我們可以列出如下：</p><ul><li>自動檢測你的終端是否支持 Sixel 圖形格式。如果你的終端不支持 Sixel，它會通知你啓用它。</li><li>自動檢測終端背景顏色。它使用終端轉義序列來試圖找出終端應用程序的前景色和背景色，並清楚地顯示縮略圖。</li><li>如果目錄中有更多圖像（通常大於 21 個），<code>lsix</code> 將一次顯示這些圖像，因此你無需等待創建整個蒙太奇圖像（LCTT 譯註：拼貼圖）。</li><li>可以通過 SSH 工作，因此你可以輕鬆操作存儲在遠程 Web 服務器上的圖像。</li><li>它支持非位圖圖形，例如 .svg、.eps、.pdf、.xcf 等。</li><li>用 Bash 編寫，適用於幾乎所有 Linux 發行版。</li></ul><h3 id="安裝-lsix" tabindex="-1">安裝 lsix <a class="header-anchor" href="#安裝-lsix" aria-label="Permalink to “安裝 lsix”">​</a></h3><p>由於 <code>lsix</code> 使用 ImageMagick，請確保已安裝它。它在大多數 Linux 發行版的默認軟件庫中都可用。 例如，在 Arch Linux 及其變體如 Antergos、Manjaro Linux 上，可以使用以下命令安裝ImageMagick：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S imagemagick</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install imagemagick</span></span></code></pre></div><p><code>lsix</code> 並不需要安裝，因為它只是一個 Bash 腳本。只需要下載它並移動到你的 <code>$PATH</code> 中。就這麼簡單。</p><p>從該項目的 GitHub 主頁下載最新的 <code>lsix</code> 版本。我使用如下命令下載 <code>lsix</code> 歸檔包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget https://github.com/hackerb9/lsix/archive/master.zip</span></span></code></pre></div><p>提取下載的 zip 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unzip master.zip</span></span></code></pre></div><p>此命令將所有內容提取到名為 <code>lsix-master</code> 的文件夾中。將 <code>lsix</code> 二進制文件從此目錄複製到 <code>$PATH</code> 中，例如 <code>/usr/local/bin/</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cp lsix-master/lsix /usr/local/bin/</span></span></code></pre></div><p>最後，使 <code>lsix</code> 二進制文件可執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod +x /usr/local/bin/lsix</span></span></code></pre></div><p>如此，現在是在終端本身顯示縮略圖的時候了。</p><p>在開始使用 <code>lsix</code> 之前，請確保你的終端支持 Sixel 圖形格式。</p><p>開發人員在 vt340 仿真模式下的 Xterm 上開發了 <code>lsix</code>。 然而，他聲稱 <code>lsix</code> 應該適用於任何Sixel 兼容終端。</p><p>Xterm 支持 Sixel 圖形格式，但默認情況下不啓用。</p><p>你可以從另外一個終端使用命令來啓動一個啓用了 Sixel 模式的 Xterm：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xterm -ti vt340</span></span></code></pre></div><p>或者，你可以使 vt340 成為 Xterm 的默認終端類型，如下所述。</p><p>編輯 <code>.Xresources</code> 文件（如果它不可用，只需創建它）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi .Xresources</span></span></code></pre></div><p>添加如下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>xterm*decTerminalID    :   vt340</span></span></code></pre></div><p>按下 <code>ESC</code> 並鍵入 <code>:wq</code> 以保存並關閉該文件。</p><p>最後，運行如下命令來應用改變：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xrdb -merge .Xresources</span></span></code></pre></div><p>現在，每次啓動 Xterm 就會默認啓用 Sixel 圖形支持。</p><h3 id="在終端中顯示縮略圖" tabindex="-1">在終端中顯示縮略圖 <a class="header-anchor" href="#在終端中顯示縮略圖" aria-label="Permalink to “在終端中顯示縮略圖”">​</a></h3><p>啓動 Xterm（不要忘記以 vt340 模式啓動它）。以下是 Xterm 在我的系統中的樣子。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/01/xterm-1.png" alt=""></p><p>就像我已經説過的那樣，<code>lsix</code> 非常簡單實用。它沒有任何命令列選項或配置文件。你所要做的就是將文件的路徑作為參數傳遞，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsix ostechnix/logo.png</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/01/lsix-4.png" alt=""></p><p>如果在沒有路徑的情況下運行它，它將顯示在當前工作目錄中的縮略圖圖像。我在名為 <code>ostechnix</code> 的目錄中有幾個文件。</p><p>要顯示此目錄中的縮略圖，只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsix</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/01/lsix-1.png" alt=""></p><p>看到了嗎？所有文件的縮略圖都顯示在終端裏。</p><p>如果使用 <code>ls</code> 命令，則只能看到文件名，而不是縮略圖。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2019/01/ls-command-1.png" alt=""></p><p>你還可以使用通配符顯示特定類型的指定圖像或一組圖像。</p><p>例如，要顯示單個圖像，只需提及圖像的完整路徑，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsix girl.jpg</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/01/lsix-2.png" alt=""></p><p>要顯示特定類型的所有圖像，例如 PNG，請使用如下所示的通配符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsix *.png</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2019/01/lsix-3.png" alt=""></p><p>對於 JEPG 類型，命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsix *jpg</span></span></code></pre></div><p>縮略圖的顯示質量非常好。我以為 <code>lsix</code> 會顯示模糊的縮略圖。但我錯了，縮略圖清晰可見，就像在圖形圖像查看器上一樣。</p><p>而且，這一切都是唾手可得。如你所見，<code>lsix</code> 與 <code>ls</code> 命令非常相似，但它僅用於顯示縮略圖。如果你在工作中處理很多圖像，<code>lsix</code> 可能會非常方便。試一試，請在下面的評論部分告訴我們你對此實用程序的看法。如果你知道任何類似的工具，也請提出建議。我將檢查並更新本指南。</p><p>更多好東西即將到來。敬請關注！</p><p>乾杯!</p><hr>',59)),e("p",null,[i[12]||(i[12]=s("via: ",-1)),l(t,{href:"https://www.ostechnix.com/how-to-display-thumbnail-images-in-terminal/"},{default:a(()=>[...i[11]||(i[11]=[s("https://www.ostechnix.com/how-to-display-thumbnail-images-in-terminal/",-1)])]),_:1})]),e("p",null,[i[17]||(i[17]=s("作者：",-1)),l(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...i[13]||(i[13]=[s("SK",-1)])]),_:1}),i[18]||(i[18]=s(" 選題：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...i[14]||(i[14]=[s("lujun9972",-1)])]),_:1}),i[19]||(i[19]=s(" 譯者：",-1)),l(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[15]||(i[15]=[s("wxy",-1)])]),_:1}),i[20]||(i[20]=s(" 校對：",-1)),l(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[16]||(i[16]=[s("wxy",-1)])]),_:1})]),e("p",null,[i[23]||(i[23]=s("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[21]||(i[21]=[s("LCTT",-1)])]),_:1}),i[24]||(i[24]=s(" 原創編譯，",-1)),l(t,{href:"https://linux.cn/"},{default:a(()=>[...i[22]||(i[22]=[s("Linux中國",-1)])]),_:1}),i[25]||(i[25]=s(" 榮譽推出",-1))])])}const w=p(h,[["render",g]]);export{y as __pageData,w as default};
